function renderSettings(){const pending=state.data.mailQueue.filter(x=>x.status==='pending').length;$('#content').innerHTML=`<div class="grid-2"><div class="card pad"><div class="section-title">Datensicherung</div><p class="muted">Export enthält Lieferanten, Ansprechpartner, Verhandlungen, Preise, Verträge, Kündigungen, Benutzer und Mail-Warteschlange. Dokumentdateien bleiben lokal.</p><div class="hr"></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="primary-btn" id="exportBtn">JSON exportieren</button><label class="secondary-btn" style="display:inline-flex;width:auto;cursor:pointer">JSON importieren<input id="importInput" type="file" accept="application/json" hidden></label></div></div><div class="card pad"><div class="section-title">Dashwise & Outlook-Automation</div><div class="notice info" style="margin-top:12px">Beim Abschluss einer Verhandlung wird automatisch eine Mail an den hinterlegten Bauleiter erzeugt und in die Versandwarteschlange gestellt. Der spätere Dashwise-Server übernimmt den tatsächlichen Outlook-Versand inklusive AB-Anhang.</div><div class="detail-grid"><div class="detail-item"><div class="k">Lieferanten</div><div class="v">${state.data.providers.length}</div></div><div class="detail-item"><div class="k">Verhandlungen</div><div class="v">${state.data.negotiations.length}</div></div><div class="detail-item"><div class="k">Mail-Warteschlange</div><div class="v">${pending}</div></div></div></div></div>`;$('#exportBtn').addEventListener('click',exportJson);$('#importInput').addEventListener('change',importJson)}
